"""
SPQR Jeopardy - single-file Render server
Everything is contained in this one Python file.
No third-party packages are required.
"""
import base64
import json
import os
import socket
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

HOST = "0.0.0.0"
PORT = int(os.environ.get("PORT", "10000"))

INDEX_HTML = base64.b64decode(
    ""
).decode("utf-8")

LOCK = threading.Lock()
PALETTE = ['#e04f5f', '#4fa3e0', '#e0b04f', '#6fbf7f', '#b06fe0', '#e0824f', '#4fd6c8', '#e04fd0']
CURSOR_TTL = 6.0
PLAYER_TTL = 15.0
REVEAL_DURATION = 2.5

def default_board():
    return {
        "cells": {f"{ci}_{vi}": {"answered": False} for ci in range(5) for vi in range(5)},
        "activeClue": None,
    }

STATE = {
    "board": default_board(),
    "players": {},
    "phase": "lobby",
    "cursors": {},
}

def cleanup_stale(now=None):
    now = now or time.time()
    stale_players = [pid for pid, p in STATE["players"].items()
                     if now - p.get("lastSeen", 0) > PLAYER_TTL]
    for pid in stale_players:
        STATE["players"].pop(pid, None)
        STATE["cursors"].pop(pid, None)
    stale_cursors = [pid for pid, c in STATE["cursors"].items()
                     if now - c.get("ts", 0) >= CURSOR_TTL or pid not in STATE["players"]]
    for pid in stale_cursors:
        STATE["cursors"].pop(pid, None)

def snapshot():
    with LOCK:
        cleanup_stale()
        return {
            "board": STATE["board"],
            "players": {
                k: {"name": v["name"], "score": v["score"], "color": v["color"]}
                for k, v in STATE["players"].items()
            },
            "phase": STATE["phase"],
            "cursors": {k: dict(v) for k, v in STATE["cursors"].items()},
        }

def apply_action(path, data):
    changed = False
    with LOCK:
        cleanup_stale()

        if path == "/api/join":
            pid = data.get("id")
            name = (data.get("name") or "Citizen").strip()[:18] or "Citizen"
            if not pid:
                return {"error": "missing id"}, 400, False
            existing = STATE["players"].get(pid)
            used = {p["color"] for p in STATE["players"].values()}
            color = next((c for c in PALETTE if c not in used),
                         PALETTE[len(STATE["players"]) % len(PALETTE)])
            STATE["players"][pid] = {
                "name": name,
                "score": existing["score"] if existing else 0,
                "color": existing["color"] if existing else color,
                "lastSeen": time.time(),
            }
            changed = True
            return {"ok": True, "color": STATE["players"][pid]["color"]}, 200, changed

        if path == "/api/cursor":
            pid = data.get("id")
            if pid in STATE["players"]:
                now = time.time()
                p = STATE["players"][pid]
                p["lastSeen"] = now
                try:
                    x = max(0.0, min(1.0, float(data.get("x", 0))))
                    y = max(0.0, min(1.0, float(data.get("y", 0))))
                except (TypeError, ValueError):
                    x, y = 0.0, 0.0
                STATE["cursors"][pid] = {
                    "name": p["name"], "color": p["color"],
                    "x": x, "y": y, "ts": now
                }
            return {"ok": True}, 200, False

        if path == "/api/leave":
            pid = data.get("id")
            if pid:
                STATE["players"].pop(pid, None)
                STATE["cursors"].pop(pid, None)
                changed = True
            return {"ok": True}, 200, changed

        if path == "/api/open_clue":
            try:
                ci, vi = int(data.get("ci")), int(data.get("vi"))
            except (TypeError, ValueError):
                return {"error": "invalid clue"}, 400, False
            key = f"{ci}_{vi}"
            cell = STATE["board"]["cells"].get(key)
            if STATE["phase"] == "playing" and cell and not cell["answered"] and STATE["board"]["activeClue"] is None:
                STATE["board"]["activeClue"] = {
                    "ci": ci, "vi": vi, "buzzedId": None, "buzzedName": None,
                    "lockedOut": [], "revealAnswer": False,
                }
                changed = True
            return {"ok": True}, 200, changed

        if path == "/api/buzz":
            ac = STATE["board"]["activeClue"]
            pid = data.get("id")
            if ac and pid in STATE["players"] and not ac["buzzedId"] and pid not in ac["lockedOut"]:
                STATE["players"][pid]["lastSeen"] = time.time()
                ac["buzzedId"] = pid
                ac["buzzedName"] = STATE["players"][pid]["name"]
                changed = True
            return {"ok": True}, 200, changed

        if path == "/api/judge":
            ac = STATE["board"]["activeClue"]
            correct = bool(data.get("correct"))
            if ac and ac["buzzedId"] in STATE["players"]:
                value = (ac["vi"] + 1) * 100
                pid = ac["buzzedId"]
                STATE["players"][pid]["score"] += value if correct else -value
                if correct:
                    STATE["board"]["cells"][f'{ac["ci"]}_{ac["vi"]}'] = {"answered": True}
                    STATE["board"]["activeClue"] = None
                else:
                    if pid not in ac["lockedOut"]:
                        ac["lockedOut"].append(pid)
                    ac["buzzedId"] = None
                    ac["buzzedName"] = None
                    if len(ac["lockedOut"]) >= max(len(STATE["players"]), 1):
                        ac["revealAnswer"] = True
                        STATE["board"]["cells"][f'{ac["ci"]}_{ac["vi"]}'] = {"answered": True}
                        clue_ref = ac
                        def clear_later():
                            time.sleep(REVEAL_DURATION)
                            with LOCK:
                                if STATE["board"]["activeClue"] is clue_ref:
                                    STATE["board"]["activeClue"] = None
                        threading.Thread(target=clear_later, daemon=True).start()
                changed = True
            return {"ok": True}, 200, changed

        if path == "/api/skip":
            ac = STATE["board"]["activeClue"]
            if ac:
                STATE["board"]["cells"][f'{ac["ci"]}_{ac["vi"]}'] = {"answered": True}
                ac["revealAnswer"] = True
                clue_ref = ac
                def clear_skipped():
                    time.sleep(REVEAL_DURATION)
                    with LOCK:
                        if STATE["board"]["activeClue"] is clue_ref:
                            STATE["board"]["activeClue"] = None
                threading.Thread(target=clear_skipped, daemon=True).start()
                changed = True
            return {"ok": True}, 200, changed

        if path == "/api/start":
            if not STATE["players"]:
                return {"error": "no players"}, 400, False
            STATE["phase"] = "playing"
            return {"ok": True}, 200, True

        if path == "/api/reset":
            STATE["board"] = default_board()
            for p in STATE["players"].values():
                p["score"] = 0
                p["lastSeen"] = time.time()
            STATE["phase"] = "lobby"
            STATE["cursors"] = {}
            return {"ok": True}, 200, True

    return {"error": "not found"}, 404, False

class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        pass

    def send_bytes(self, body, content_type, status=200, cache="no-store"):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", cache)
        self.send_header("Connection", "keep-alive")
        self.end_headers()
        self.wfile.write(body)

    def send_json(self, obj, status=200):
        body = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        self.send_bytes(body, "application/json; charset=utf-8", status)

    def read_json(self):
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length <= 0 or length > 1000000:
                return {}
            return json.loads(self.rfile.read(length).decode("utf-8"))
        except Exception:
            return {}

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.end_headers()

    def do_GET(self):
        path = self.path.split("?")[0]

        if path == "/" or path == "/index.html":
            self.send_bytes(INDEX_HTML.encode("utf-8"), "text/html; charset=utf-8",
                            cache="public, max-age=300")
            return

        if path == "/api/health":
            self.send_json({"ok": True})
            return

        if path == "/api/state":
            query = parse_qs(urlparse(self.path).query)
            pid = (query.get("id") or [None])[0]
            with LOCK:
                now = time.time()
                if pid in STATE["players"]:
                    STATE["players"][pid]["lastSeen"] = now
                cleanup_stale(now)
            self.send_json(snapshot())
            return

        self.send_bytes(b"Not found", "text/plain; charset=utf-8", 404)

    def do_POST(self):
        result, status, changed = apply_action(self.path.split("?")[0], self.read_json())
        self.send_json(result, status)

if __name__ == "__main__":
    server = ThreadingHTTPServer((HOST, PORT), Handler)
    print(f"SPQR Jeopardy running on 0.0.0.0:{PORT}")
    print(f"Render/local URL: http://localhost:{PORT}")
    server.serve_forever()
